// Tight Wind Strike loop on nearest attackable NPC
const WIND_STRIKE = 1152;
const start = Date.now();
const end = start + 30000;
let casts = 0;
let xpStart = sdk.getSkillXp('Magic');
while (Date.now() < end) {
  const r = await bot.castSpellOnNpc(/^(Rat|Man|Woman)$/i, WIND_STRIKE, 4000);
  if (r.success) casts++;
  else {
    // out of runes or no npc
    if (r.reason === 'no_runes') { console.log('OUT OF RUNES', r.message); break; }
  }
}
const xpEnd = sdk.getSkillXp('Magic');
console.log(`casts=${casts} xp=${xpEnd-xpStart} elapsed=${((Date.now()-start)/1000).toFixed(1)}s`);
return { casts, xp: xpEnd - xpStart, elapsed: (Date.now()-start)/1000 };

const code = await (async () => {
  const WIND_STRIKE = 1152;
  const start = Date.now();
  const end = start + 30000;
  let casts = 0, fails = 0;
  const xpStart = sdk.getSkillXp('Magic');
  while (Date.now() < end) {
    const r = await bot.castSpellOnNpc(/^(Rat|Man|Woman)$/i, WIND_STRIKE, 4000);
    if (r.success) casts++;
    else { fails++; if (r.reason === 'no_runes') { console.log('OUT OF RUNES'); break; } }
  }
  const xpEnd = sdk.getSkillXp('Magic');
  return { casts, fails, xp: xpEnd - xpStart, elapsed: (Date.now()-start)/1000 };
})();
return code;

