import { BotSDK, BotActions, deriveGatewayUrl } from '/app/sdk/index.ts';

const sdk = new BotSDK({
    botUsername: 'agent',
    password: 'test',
    gatewayUrl: deriveGatewayUrl('localhost'),
    autoReconnect: true,
    autoLaunchBrowser: false
});
const bot = new BotActions(sdk);
await sdk.connect();
await sdk.waitForCondition(s => s !== null, 10000);

await sdk.sendSetCombatStyle(1);
await sdk.waitForTicks(2);
const start = Date.now();
const startStr = sdk.getSkillXp('strength');
let kills = 0;
const end = Date.now() + 80000;
while (Date.now() < end) {
  const st = sdk.getState();
  if (!st) { await sdk.waitForTicks(2); continue; }
  if (st.player.combat.inCombat) { await sdk.waitForTicks(1); continue; }
  const npcs = (st.nearbyNpcs || []).filter(n =>
    n.options.some(o => /attack/i.test(o)) && !n.inCombat && n.hp > 0 && n.distance <= 14
  ).sort((a,b)=>a.distance-b.distance);
  if (npcs.length === 0) { await sdk.waitForTicks(2); continue; }
  const r = await bot.attackNpc(npcs[0]);
  if (r.success) { kills++; await sdk.waitForTicks(1); }
}
const dstr = sdk.getSkillXp('strength') - startStr;
console.log('kills', kills, 'strXP gained', dstr, 'in', (Date.now()-start)/1000, 's');
return {kills, dstr};

