async function walkTo2(tx, tz, maxSteps=40){
  for (let i=0;i<maxSteps;i++){
    const s = sdk.getState();
    let x=s.player.worldX, z=s.player.worldZ;
    if (Math.abs(x-tx)<=0 && Math.abs(z-tz)<=0) return 'arrived';
    // try direct step first (prefer x then z), then diagonals via single-axis
    const dx = Math.sign(tx-x), dz=Math.sign(tz-z);
    const cands = [];
    if (dx) cands.push([x+dx, z]);
    if (dz) cands.push([x, z+dz]);
    if (dx&&dz) cands.push([x+dx, z+dz]);
    cands.push([x+dx, z-dz],[x-dx, z+dz]);
    let moved=false;
    for (const [nx,nz] of cands){
      if (nx===x && nz===z) continue;
      await sdk.sendWalk(nx,nz,false);
      await sdk.waitForTicks(3);
      const s2=sdk.getState();
      if (s2.player.worldX!==x || s2.player.worldZ!==z){ moved=true; break; }
    }
    if(!moved){ await sdk.waitForTicks(2); }
  }
  return 'timeout';
}
